COMMENT ON COLUMN "users"."pin_hash" IS 'Store managers only: hashed 6-digit PIN (UC12). The counter checks the PIN against every active manager, so two managers may not share one';

COMMENT ON COLUMN "counters"."code" IS 'Q1, Q2, …';

COMMENT ON COLUMN "counters"."camera_url" IS 'Snapshot URL of the IP camera; the backend pulls the tray image from it';

COMMENT ON COLUMN "counters"."camera_last_seen_at" IS 'Heartbeat; the camera is online when seen in the last 30 seconds';

COMMENT ON COLUMN "counters"."pin_failed_attempts" IS 'Wrong manager PINs at this counter; the PIN does not say which manager was meant';

COMMENT ON COLUMN "counters"."pin_locked_until" IS '3 wrong PINs lock PIN entry at this counter for 5 minutes (US08)';

COMMENT ON COLUMN "shifts"."counted_cash_vnd" IS 'Cash counted at close; the expected amount is derived from cash payments';

COMMENT ON COLUMN "categories"."code" IS 'e.g. puffed_food; suspected swaps compare SKUs of one category';

COMMENT ON COLUMN "skus"."barcode" IS 'EAN-13; demo SKUs use the in-store prefix 200 (BR-14)';

COMMENT ON COLUMN "skus"."price_vnd" IS 'Current price; lines keep the price at the time of sale';

COMMENT ON COLUMN "skus"."batch_id" IS 'Batch that teaches this SKU to the camera; NULL = not in a batch yet';

COMMENT ON COLUMN "transactions"."code" IS 'Receipt number, e.g. GD1000';

COMMENT ON COLUMN "transactions"."shift_id" IS 'Gives the counter and the cashier';

COMMENT ON COLUMN "transactions"."status" IS 'Waiting for alerts / ready to pay are derived from the open HIGH alerts';

COMMENT ON COLUMN "transactions"."total_vnd" IS 'Set at payment: sum of the lines not removed';

COMMENT ON COLUMN "transactions"."started_at" IS 'First scan; the tray is photographed now, while the items are still on the counter';

COMMENT ON COLUMN "transactions"."reconciled_at" IS 'Cross-check: first press of Pay, photo compared with the scans (UC05). From then on every scan or removal re-runs it';

COMMENT ON COLUMN "transactions"."closed_at" IS 'Paid or cancelled';

COMMENT ON COLUMN "transaction_lines"."unit_price_vnd" IS 'Price at the time of sale (BR-06)';

COMMENT ON COLUMN "transaction_lines"."detection_id" IS 'Fast lane: box the camera added this line from';

COMMENT ON COLUMN "transaction_lines"."removed_at" IS 'Deleted lines are kept for the post-review (BR-17)';

COMMENT ON COLUMN "transaction_lines"."removed_by" IS 'Cashier who deleted the line, without a PIN (BR-05)';

COMMENT ON COLUMN "tray_captures"."model_version_id" IS 'Model that ran the detection (BR-06)';

COMMENT ON COLUMN "tray_captures"."image_key" IS 'Object storage key of the tray image';

COMMENT ON COLUMN "tray_captures"."image_purged_at" IS 'Image deleted after 30 days (BR-13); detections and alerts stay';

COMMENT ON COLUMN "detections"."sku_id" IS 'SKU predicted by the model';

COMMENT ON COLUMN "detections"."confirmed_sku_id" IS 'Fast lane: SKU scanned to confirm an uncertain box; differs from sku_id when corrected';

COMMENT ON COLUMN "alerts"."capture_id" IS 'Tray photo the scans were compared with; gives the transaction';

COMMENT ON COLUMN "alerts"."seen_sku_id" IS 'SKU the camera saw: the unscanned item, or the real item of a swap';

COMMENT ON COLUMN "alerts"."scanned_sku_id" IS 'SKU that was scanned: swap, or scanned but not seen';

COMMENT ON COLUMN "alerts"."value_vnd" IS 'Money at risk for the store';

COMMENT ON COLUMN "alerts"."reason" IS 'Cashier reason for a false alarm (BR-04)';

COMMENT ON COLUMN "alerts"."resolved_by" IS 'Cashier who scanned or confirmed the false alarm';

COMMENT ON COLUMN "alerts"."review_result" IS 'Post-review of a false alarm by the manager (UC14, BR-17)';

COMMENT ON TABLE "alert_detections" IS 'Boxes that raised an alert, highlighted on the tray image. capture_id makes both sides belong to one tray photo';

COMMENT ON TABLE "manager_approvals" IS 'Manager PIN confirmations at the counter: cancel a transaction, skip the tray check (UC12, BR-05)';

COMMENT ON COLUMN "manager_approvals"."requested_by" IS 'Cashier at the counter';

COMMENT ON COLUMN "import_batches"."seq_no" IS 'Shown as "Đợt 5"; also the order in which the model learns batches';

COMMENT ON COLUMN "import_batches"."data_purged_at" IS 'Sample photos and TRAIN real images deleted 14 days after deploy; VAL images stay for the gates of later versions (BR-13)';

COMMENT ON TABLE "sku_samples" IS 'Sample photos of a new SKU and their background-removed cutouts (UC17)';

COMMENT ON COLUMN "sku_samples"."cutout_key" IS 'NULL while background removal runs';

COMMENT ON COLUMN "sku_samples"."mask_quality" IS 'From the background-removal model; low values are flagged for a closer look';

COMMENT ON TABLE "label_tasks" IS 'Real tray images labelled with the assistant (UC18)';

COMMENT ON COLUMN "label_tasks"."batch_id" IS 'NULL: hard image waiting for the next batch';

COMMENT ON COLUMN "label_tasks"."capture_id" IS 'Source image; one task per image';

COMMENT ON COLUMN "label_tasks"."image_key" IS 'Copy in the dataset store, so the 30-day transaction retention does not delete it';

COMMENT ON COLUMN "label_tasks"."split" IS 'VAL first; TRAIN only above the BR-11 target, when the ML engineer opts in (BR-16)';

COMMENT ON COLUMN "label_tasks"."proposals_total" IS 'Old-SKU boxes proposed by the model';

COMMENT ON COLUMN "label_tasks"."queued_by" IS 'NULL: queued by the system';

COMMENT ON COLUMN "label_tasks"."completed_by" IS 'Labelled or skipped by';

COMMENT ON TABLE "annotations" IS 'Accepted boxes only: a proposal becomes a label once a person accepts it (BR-12)';

COMMENT ON COLUMN "annotations"."proposal_score" IS 'Score of the accepted model proposal';

COMMENT ON TABLE "jobs" IS 'Background work of a batch: composites, training, evaluation (UC19, UC20)';

COMMENT ON COLUMN "jobs"."progress_total" IS 'Epochs for training, images for composites';

COMMENT ON COLUMN "jobs"."params" IS 'e.g. {"epochs": 16, "mix_real_images": 2, "composite_job_id": 7}';

COMMENT ON COLUMN "jobs"."output_uri" IS 'Composite dataset folder or checkpoint folder';

COMMENT ON COLUMN "jobs"."output_count" IS 'Composites created';

COMMENT ON COLUMN "model_versions"."code" IS 'v1, v2, …';

COMMENT ON COLUMN "model_versions"."batch_id" IS 'Last batch learned; the version also knows every earlier batch';

COMMENT ON COLUMN "model_versions"."ap50" IS 'Metrics in %, on the real-image validation set (BR-09)';

COMMENT ON COLUMN "model_versions"."forgetting" IS 'Mean AP50 drop on earlier batches, points';

COMMENT ON COLUMN "model_versions"."false_alarm_rate" IS 'Alerted trays among trays scanned completely and correctly';

COMMENT ON COLUMN "model_versions"."gate_report" IS 'Each BR-09 condition: value, baseline of the running version, limit, passed';

COMMENT ON TABLE "model_version_skus" IS 'Class map of a version: which SKUs it knows. A SKU is learned when the ACTIVE version lists it';

COMMENT ON COLUMN "model_version_skus"."class_index" IS 'Output index of the model head';

COMMENT ON TABLE "model_deployments" IS 'Every deploy and rollback, newest first in the UI (BR-07, BR-08)';

COMMENT ON COLUMN "model_deployments"."model_version_id" IS 'Version put into service';

COMMENT ON COLUMN "model_deployments"."previous_version_id" IS 'Version it replaced; NULL for the first deploy';

COMMENT ON COLUMN "model_deployments"."reason" IS 'Required for an override and for a rollback';

COMMENT ON TABLE "model_confusions" IS 'Most confused SKU pairs of a version on validation (L05)';

COMMENT ON TABLE "threshold_configs" IS 'Append-only history: the newest row per batch is in force; undo inserts the old values again (L06)';

COMMENT ON COLUMN "threshold_configs"."batch_id" IS 'Applies to the SKUs of this batch (BR-10)';

COMMENT ON COLUMN "threshold_configs"."low_threshold" IS 'Below: ignored. Between low and alert: drawn as uncertain only';

COMMENT ON COLUMN "threshold_configs"."alert_threshold" IS 'At or above: counts as seen and can raise alerts';

COMMENT ON COLUMN "threshold_configs"."auto_threshold" IS 'Fast lane: at or above, added to the cart without a scan';

COMMENT ON TABLE "settings" IS 'Tunable rules (retention, gate, audit, data targets); defaults in extras.sql';

COMMENT ON TABLE "audit_logs" IS 'Append-only: a trigger rejects UPDATE, DELETE and TRUNCATE (US27)';

COMMENT ON COLUMN "audit_logs"."actor_id" IS 'NULL: the system';

COMMENT ON COLUMN "audit_logs"."action" IS 'LOGIN, PIN_FAILED, FALSE_ALARM, DELETE_LINE, DEPLOY_MODEL, …';

COMMENT ON COLUMN "audit_logs"."entity_type" IS 'transaction, sku, import_batch, model_version, …';

